async function purchases(){loading();const d=await api('community_purchases'),pending=(d.plans||[]).filter(x=>x.status!=='realizada'),done=(d.plans||[]).filter(x=>x.status==='realizada');const card=p=>`<article class="community-purchase-card ${p.status==='realizada'?'is-completed':''}"><div class="community-purchase-date"><strong>${new Intl.DateTimeFormat('es-AR',{month:'short'}).format(new Date(p.plan_month+'T12:00:00')).toUpperCase()}</strong><span>${String(p.plan_month).slice(0,4)}</span></div><div class="community-purchase-info"><span class="badge">${cap(p.status)}</span><h3>${h(p.title)}</h3><p>Propuesta por ${h(p.proposed_by_name||'—')} · ${Number(p.item_count||0)} elementos</p></div><div class="community-purchase-amount"><small>Total estimado</small><strong>${moneyARS(p.total_amount)}</strong><a class="btn btn-small btn-secondary" href="#/compra-comunidad/${p.id}">Abrir compra</a></div></article>`;shell({title:'Compras comunitarias',subtitle:'Planificar primero y registrar con claridad quién compra y quién paga',active:'purchases',actions:'<a class="btn btn-primary" href="#/compra-comunidad">+ Nueva compra</a>',content:`<section class="purchase-explainer panel"><div>1</div><p><strong>Planificar</strong><span>Agregue los elementos, cantidades y precios estimados.</span></p><div>2</div><p><strong>Comprar</strong><span>Al terminar, indique quién pagó y si el gasto fue comunitario o personal.</span></p><div>3</div><p><strong>Recibir</strong><span>Los elementos se convierten automáticamente en materiales disponibles.</span></p></section><section class="panel"><div class="panel-header"><div><h2>Pendientes</h2><p>Compras que todavía deben realizarse</p></div><strong>${pending.length}</strong></div>${pending.length?`<div class="community-purchase-list">${pending.map(card).join('')}</div>`:empty('▤','No hay compras pendientes','Cree una tarjeta para el próximo mes.')}</section><section class="panel completed-purchases-panel"><div class="panel-header"><div><h2>Realizadas</h2><p>Histórico de compras cerradas</p></div><strong>${done.length}</strong></div>${done.length?`<div class="community-purchase-list">${done.map(card).join('')}</div>`:'<p class="muted">Todavía no hay compras realizadas.</p>'}</section>`})}
async function purchase(id=0){loading();const d=await api('community_purchase',{params:{id}}),p=d.plan,total=(d.items||[]).reduce((sum,x)=>sum+Number(x.total||0),0);shell({title:p?p.title:'Nueva compra',subtitle:p?'Detalle de planificación y realización':'Crear una compra comunitaria',active:'purchases',actions:'<a class="btn btn-ghost" href="#/compras-comunidad">Volver</a>',content:`<div class="purchase-detail-layout"><section class="form-card"><div class="panel-header"><div><h2>${p?'Datos de la compra':'Nueva planificación'}</h2><p>La persona que la crea queda registrada automáticamente.</p></div></div><form data-form="purchase-save"><input type="hidden" name="id" value="${p?.id||''}"><label class="field"><span>Título</span><input name="title" required value="${h(p?.title||'')}" placeholder="Ej. Materiales para primavera"></label><label class="field"><span>Mes</span><input type="month" name="plan_month" value="${h(p?.plan_month?.slice(0,7)||monthNow())}" required></label><label class="field"><span>Notas</span><textarea name="notes">${h(p?.notes||'')}</textarea></label><button class="btn btn-primary">Guardar compra</button></form></section>${p?`<section class="panel purchase-items-panel"><div class="purchase-total-hero"><div><span>${p.status==='pendiente'?'Total estimado':'Total realizado'}</span><strong>${moneyARS(total)}</strong><small>${(d.items||[]).length} elementos</small></div>${p.status==='pendiente'?`<button class="btn btn-success" data-command="purchase-complete" data-id="${p.id}">MARCAR REALIZADA</button>`:`<div class="purchase-completed-by"><strong>Compra cerrada</strong><span>Realizó: ${h(p.completed_by_name||'—')}</span><span>Pagó: ${h(p.paid_by_name||'—')}</span></div>`}</div>${p.status==='pendiente'?`<form class="purchase-item-form community-purchase-item-form" data-form="purchase-item-save"><input type="hidden" name="plan_id" value="${p.id}"><input name="item_name" placeholder="Elemento" required><input type="number" step="1" min="1" name="quantity" value="1" required><input type="number" step="0.01" name="unit_price" placeholder="Precio unitario"><input name="purchase_place" placeholder="Lugar de compra"><button class="btn btn-secondary">Agregar</button></form>`:''}<div class="community-purchase-items">${(d.items||[]).map(i=>`<article><div><strong>${h(i.item_name)}</strong><small>${h(i.purchase_place||'Lugar sin indicar')}</small></div><span>${integerQty(i.quantity)} × ${moneyARS(i.unit_price)}</span><b>${moneyARS(i.total)}</b>${p.status==='pendiente'?`<button class="icon-button danger" data-command="purchase-item-delete" data-id="${i.id}">×</button>`:''}</article>`).join('')}</div></section>`:''}</div>`})}
async function completePurchase(id){const d=await api('community_purchase',{params:{id}});modal('Marcar compra como realizada',`<form data-form="purchase-complete"><div class="modal-info-box"><strong>Al confirmar</strong><span>La compra se cerrará y sus elementos se agregarán a Materiales como disponibles.</span></div><label class="field"><span>Quién pagó</span><select name="paid_by_user_id"><option value="">Sin indicar</option>${d.people.map(p=>`<option value="${p.id}">${h(p.display_name)}</option>`).join('')}</select></label><label class="field"><span>Tipo de gasto</span><select name="expense_scope"><option value="comunitario">Comunitario</option><option value="personal">Personal</option></select></label><input type="hidden" name="id" value="${id}"><button class="btn btn-success">Confirmar realizada</button></form>`,false)}
async function accounting(params){loading();const f={from:params.get('from')||'',to:params.get('to')||'',type:params.get('type')||'',person_id:params.get('person_id')||'',concept_id:params.get('concept_id')||'',q:params.get('q')||''},d=await api('community_accounting',{params:f}),sm=d.summary||{};shell({title:'Contabilidad comunitaria',subtitle:'Movimientos visibles para todos los integrantes',active:'accounting',actions:'<a class="btn btn-secondary" href="#/contabilidad-propia">Abrir mi contabilidad privada</a>',content:`<section class="accounting-hero community-accounting-hero"><div><span>Balance general</span><strong>${moneyUSD(sm.balance_usd)}</strong><small>${moneyARS(sm.balance_ars)}</small></div><div class="accounting-hero-split"><span><b>${moneyUSD(sm.income_usd)}</b><small>Ingresos</small></span><span><b>${moneyUSD(sm.expense_usd)}</b><small>Egresos</small></span></div></section><div class="split-layout community-accounting-layout"><section class="form-card sticky-panel"><div class="panel-header"><div><h2>Nuevo movimiento compartido</h2><p>Será visible para las cuatro personas.</p></div></div><form data-form="account-save" enctype="multipart/form-data"><label class="field"><span>Fecha</span><input type="date" name="entry_date" value="${today()}" required></label><label class="field"><span>A quién corresponde</span><select name="person_user_id"><option value="">Comunidad</option>${d.people.map(p=>`<option value="${p.id}">${h(p.display_name)}</option>`).join('')}</select></label><div class="form-grid two-columns"><label class="field"><span>Tipo</span><select name="movement_type"><option value="egreso">Egreso</option><option value="ingreso">Ingreso</option></select></label><label class="field"><span>Concepto</span><select name="concept_id" required>${d.concepts.map(c=>`<option value="${c.id}">${h(c.name)}</option>`).join('')}</select></label></div><label class="field"><span>Importe en pesos</span><input type="number" step=".01" name="amount_ars" required></label><label class="field"><span>Cotización del dólar</span><input type="number" step=".0001" name="usd_rate" required></label><label class="field"><span>Descripción</span><textarea name="description"></textarea></label><label class="field"><span>Comprobante</span><input type="file" name="receipt" accept="application/pdf,image/jpeg,image/png,image/webp"></label><button class="btn btn-primary">Guardar movimiento</button></form></section><section class="panel"><form class="filter-bar" data-form="account-filter"><input type="date" name="from" value="${f.from}"><input type="date" name="to" value="${f.to}"><select name="person_id"><option value="">Todas las personas</option>${d.people.map(p=>`<option value="${p.id}" ${String(f.person_id)===String(p.id)?'selected':''}>${h(p.display_name)}</option>`).join('')}</select><select name="type"><option value="">Ingresos y egresos</option><option value="ingreso" ${f.type==='ingreso'?'selected':''}>Ingresos</option><option value="egreso" ${f.type==='egreso'?'selected':''}>Egresos</option></select><button class="btn btn-secondary">Filtrar</button></form>${(d.entries||[]).length?`<div class="accounting-movement-list">${d.entries.map(e=>`<article class="accounting-movement ${e.movement_type}"><div class="movement-date"><strong>${fmt(e.entry_date)}</strong><span>${h(e.person_name||'Comunidad')}</span></div><div class="movement-info"><span class="badge">${h(e.concept_name)}</span><p>${h(e.description||'Sin descripción')}</p><small>Cargó: ${h(e.created_by_name||'—')}</small></div><div class="movement-amount"><strong>${e.movement_type==='egreso'?'-':'+'} ${moneyUSD(e.amount_usd)}</strong><span>${moneyARS(e.amount_ars)}</span></div><div>${e.receipt_relative_path?`<button class="file-link" data-command="open-file" data-type="receipt" data-id="${e.id}">Comprobante</button>`:''}<button class="icon-button danger" data-command="account-delete" data-id="${e.id}">×</button></div></article>`).join('')}</div>`:empty('$','Sin movimientos','No hay registros para los filtros elegidos.')}</section></div>`})}

const communityDocCategories={renapa:'RENAPA',senasa:'SENASA',registro:'Registro',certificado:'Certificado',contrato:'Contrato',seguro:'Seguro',plano:'Plano',factura:'Factura',manual:'Manual',otro:'Otro'};
async function openGenericDocument(id,name='documento'){const b=await api('document_file',{params:{app_code:'comunidad',id},blob:true}),u=URL.createObjectURL(b);state.urls.push(u);const w=open(u,'_blank','noopener');if(!w){const a=document.createElement('a');a.href=u;a.download=name;a.click()}}
function communityDocumentModal(doc={}){modal(doc.id?'Editar documento':'Agregar documento',`<form data-form="community-document-save" enctype="multipart/form-data"><input type="hidden" name="app_code" value="comunidad"><input type="hidden" name="id" value="${doc.id||''}"><div class="form-grid two-columns"><label class="field"><span>Nombre *</span><input name="title" required value="${h(doc.title||'')}"></label><label class="field"><span>Categoría</span><select name="category">${Object.entries(communityDocCategories).map(([v,l])=>`<option value="${v}" ${doc.category===v?'selected':''}>${l}</option>`).join('')}</select></label><label class="field"><span>Número</span><input name="document_number" value="${h(doc.document_number||'')}"></label><label class="field"><span>Organismo o emisor</span><input name="issuer" value="${h(doc.issuer||'')}"></label><label class="field"><span>Emisión</span><input type="date" name="issue_date" value="${h(doc.issue_date||'')}"></label><label class="field"><span>Vencimiento</span><input type="date" name="expiry_date" value="${h(doc.expiry_date||'')}"></label></div><label class="field"><span>Notas</span><textarea name="notes">${h(doc.notes||'')}</textarea></label><label class="field"><span>${doc.id?'Reemplazar archivo':'Archivo *'}</span><input type="file" name="document" accept="application/pdf,image/jpeg,image/png,image/webp" ${doc.id?'':'required'}></label><div class="form-actions"><button class="btn btn-primary">Guardar</button><button type="button" class="btn btn-ghost" data-command="modal-close">Cancelar</button></div></form>`,false)}
async function documents(params){loading();const f={q:params.get('q')||'',category:params.get('category')||'',status:params.get('status')||''},d=await api('documents_list',{params:{app_code:'comunidad',...f}});state.documents=d.documents||[];const sm=d.summary||{};shell({title:'Documentos',subtitle:'Archivos compartidos de la Comunidad Apícola',active:'documents',actions:'<button class="btn btn-primary" data-command="document-new">+ Agregar documento</button>',content:`<section class="summary-cards document-summary"><div><span>Total</span><strong>${Number(sm.total||0)}</strong><small>Documentos compartidos</small></div><div class="warning"><span>Por vencer</span><strong>${Number(sm.expiring||0)}</strong><small>Próximos 45 días</small></div><div class="danger"><span>Vencidos</span><strong>${Number(sm.expired||0)}</strong><small>Requieren revisión</small></div></section><form class="filter-bar" data-form="document-filter"><input name="q" value="${h(f.q)}" placeholder="Buscar documento"><select name="category"><option value="">Todas las categorías</option>${Object.entries(communityDocCategories).map(([v,l])=>`<option value="${v}" ${f.category===v?'selected':''}>${l}</option>`).join('')}</select><select name="status"><option value="">Todos</option><option value="vigente" ${f.status==='vigente'?'selected':''}>Vigentes</option><option value="por_vencer" ${f.status==='por_vencer'?'selected':''}>Por vencer</option><option value="vencido" ${f.status==='vencido'?'selected':''}>Vencidos</option></select><button class="btn btn-secondary">Filtrar</button></form>${(d.documents||[]).length?`<section class="document-grid">${d.documents.map(x=>{const days=x.days_to_expiry===null?null:Number(x.days_to_expiry);const label=days===null?'Sin vencimiento':days<0?`Vencido hace ${Math.abs(days)} días`:days<=45?`Vence en ${days} días`:`Vence ${fmt(x.expiry_date)}`;return `<article class="document-card ${days!==null&&days<0?'is-expired':days!==null&&days<=45?'is-expiring':''}"><div class="document-card-icon">${String(x.mime_type).includes('pdf')?'PDF':'IMG'}</div><div class="document-card-body"><span class="document-category">${h(communityDocCategories[x.category]||'Otro')}</span><h3>${h(x.title)}</h3><p>${h(x.issuer||'Sin emisor')}${x.document_number?` · Nº ${h(x.document_number)}`:''}</p><div class="document-expiry">${h(label)}</div><small>Subió: ${h(x.uploaded_by_name||'—')}</small></div><div class="document-card-actions"><button class="btn btn-small btn-primary" data-command="document-open" data-id="${x.id}" data-name="${h(x.original_name)}">Abrir</button><button class="btn btn-small btn-ghost" data-command="document-edit" data-id="${x.id}">Editar</button><button class="icon-button danger" data-command="document-delete" data-id="${x.id}">×</button></div></article>`}).join('')}</section>`:empty('▤','No hay documentos','Agregue RENAPA, certificados, actas o archivos de la comunidad.')}`})}
async function personalAccounting(params){loading();const f={from:params.get('from')||'',to:params.get('to')||'',type:params.get('type')||'',concept_id:params.get('concept_id')||'',q:params.get('q')||''},d=await api('community_personal_accounting',{params:f}),sm=d.summary||{};shell({title:'Contabilidad propia',subtitle:'Solo usted puede ver estos movimientos y comprobantes',active:'personal-accounting',content:`<section class="private-accounting-banner"><span>🔒</span><div><strong>Espacio privado de ${h(state.user?.display_name||'usuario')}</strong><p>Ningún otro integrante de la comunidad puede consultar, descargar ni borrar esta información.</p></div></section><section class="accounting-hero private-accounting-hero"><div><span>Mi balance</span><strong>${moneyUSD(sm.balance_usd)}</strong><small>${moneyARS(sm.balance_ars)}</small></div><div class="accounting-hero-split"><span><b>${moneyUSD(sm.income_usd)}</b><small>Ingresos</small></span><span><b>${moneyUSD(sm.expense_usd)}</b><small>Egresos</small></span></div></section><div class="split-layout"><section class="form-card sticky-panel"><h2>Agregar movimiento privado</h2><form data-form="personal-account-save" enctype="multipart/form-data"><label class="field"><span>Fecha</span><input type="date" name="entry_date" value="${today()}" required></label><div class="form-grid two-columns"><label class="field"><span>Tipo</span><select name="movement_type"><option value="egreso">Egreso</option><option value="ingreso">Ingreso</option></select></label><label class="field"><span>Concepto</span><select name="concept_id" required>${d.concepts.map(c=>`<option value="${c.id}">${h(c.name)}</option>`).join('')}</select></label></div><label class="field"><span>Importe en pesos</span><input type="number" step=".01" name="amount_ars" required></label><label class="field"><span>Cotización del dólar</span><input type="number" step=".0001" name="usd_rate" required></label><label class="field"><span>Descripción</span><textarea name="description"></textarea></label><label class="field"><span>Comprobante privado</span><input type="file" name="receipt" accept="application/pdf,image/jpeg,image/png,image/webp"></label><button class="btn btn-primary">Guardar en mi cuenta</button></form></section><section class="panel"><form class="filter-bar" data-form="personal-account-filter"><input type="date" name="from" value="${f.from}"><input type="date" name="to" value="${f.to}"><select name="type"><option value="">Ingresos y egresos</option><option value="ingreso" ${f.type==='ingreso'?'selected':''}>Ingresos</option><option value="egreso" ${f.type==='egreso'?'selected':''}>Egresos</option></select><button class="btn btn-secondary">Filtrar</button></form>${(d.entries||[]).length?`<div class="accounting-movement-list">${d.entries.map(e=>`<article class="accounting-movement ${e.movement_type}"><div class="movement-date"><strong>${fmt(e.entry_date)}</strong><span>Privado</span></div><div class="movement-info"><span class="badge">${h(e.concept_name)}</span><p>${h(e.description||'Sin descripción')}</p></div><div class="movement-amount"><strong>${e.movement_type==='egreso'?'-':'+'} ${moneyUSD(e.amount_usd)}</strong><span>${moneyARS(e.amount_ars)}</span></div><div>${e.receipt_relative_path?`<button class="file-link" data-command="open-file" data-type="personal_receipt" data-id="${e.id}">Comprobante</button>`:''}<button class="icon-button danger" data-command="personal-account-delete" data-id="${e.id}">×</button></div></article>`).join('')}</div>`:empty('🔒','Sin movimientos privados','Lo que cargue aquí será visible únicamente para usted.')}</section></div>`})}
function queenModal(item={}){const hs=state.queenHives||[];modal(item.id?'Actualizar crianza':'Nueva crianza de reinas',`<form data-form="queen-rearing-save"><input type="hidden" name="app_code" value="comunidad"><input type="hidden" name="id" value="${item.id||''}"><div class="form-grid two-columns"><label class="field"><span>Nombre o lote *</span><input name="name" required value="${h(item.name||'')}"></label><label class="field"><span>Colmena de origen</span><select name="source_hive_id"><option value="">Sin especificar</option>${hs.map(x=>`<option value="${x.id}" ${String(item.source_hive_id||'')===String(x.id)?'selected':''}>${h(x.name)}</option>`).join('')}</select></label><label class="field"><span>Dónde quedó instalado</span><input name="location" value="${h(item.location||'')}"></label><label class="field"><span>Punto de inicio</span><select name="start_point"><option value="huevo" ${item.start_point==='huevo'?'selected':''}>Huevo (aprox. 16 días)</option><option value="traslarve" ${!item.start_point||item.start_point==='traslarve'?'selected':''}>Traslarve (aprox. 12 días)</option><option value="celda_operculada" ${item.start_point==='celda_operculada'?'selected':''}>Celda operculada (aprox. 6 días)</option></select></label><label class="field"><span>Fecha de inicio</span><input type="date" name="start_date" value="${item.start_date||today()}" required></label><label class="field"><span>Días estimados</span><input type="number" min="1" max="30" name="estimated_days" value="${item.estimated_days||12}"></label><label class="field"><span>Reinas proyectadas</span><input type="number" min="0" name="projected_queens" value="${item.projected_queens||0}"></label><label class="field"><span>Estado</span><select name="status">${[['planificada','Planificada'],['en_proceso','En proceso'],['nacidas','Nacidas'],['finalizada','Finalizada'],['cancelada','Cancelada']].map(([v,l])=>`<option value="${v}" ${item.status===v?'selected':''}>${l}</option>`).join('')}</select></label><label class="field"><span>Reinas obtenidas</span><input type="number" min="0" name="emerged_queens" value="${item.emerged_queens??''}"></label><label class="field"><span>Colmenas formadas</span><input type="number" min="0" name="formed_hives" value="${item.formed_hives??''}"></label></div><label class="field"><span>Observaciones</span><textarea name="notes">${h(item.notes||'')}</textarea></label><div class="estimate-note">El sistema calcula el nacimiento estimado y agrega el evento al calendario comunitario.</div><button class="btn btn-primary">Guardar</button></form>`,true)}
async function queenRearing(params){loading();const status=params.get('status')||'',d=await api('queen_rearing_list',{params:{app_code:'comunidad',status}});state.queenBatches=d.batches||[];state.queenHives=d.hives||[];shell({title:'Crianza de reinas',subtitle:'Proyección, fechas y resultados del trabajo comunitario',active:'queen-rearing',actions:'<button class="btn btn-primary" data-command="queen-rearing-new">+ Iniciar crianza</button>',content:`<form class="filter-bar" data-form="queen-rearing-filter"><select name="status"><option value="">Todos los estados</option>${[['planificada','Planificada'],['en_proceso','En proceso'],['nacidas','Nacidas'],['finalizada','Finalizada'],['cancelada','Cancelada']].map(([v,l])=>`<option value="${v}" ${status===v?'selected':''}>${l}</option>`).join('')}</select><button class="btn btn-secondary">Filtrar</button></form>${(d.batches||[]).length?`<section class="queen-rearing-grid">${d.batches.map(q=>`<article class="queen-rearing-card status-${h(q.status)}"><div class="queen-rearing-date"><small>Nacimiento estimado</small><strong>${fmt(q.expected_emergence_date)}</strong><span>${Number(q.days_remaining)>=0?`Faltan ${q.days_remaining} días`:'Fecha cumplida'}</span></div><div class="queen-rearing-body"><span class="badge">${cap(q.status)}</span><h3>${h(q.name)}</h3><p>${h(q.location||'Ubicación sin especificar')}${q.source_hive_name?` · ${h(q.source_hive_name)}`:''}</p><div class="queen-rearing-counts"><span><b>${q.projected_queens||0}</b> proyectadas</span><span><b>${q.emerged_queens??'—'}</b> obtenidas</span><span><b>${q.formed_hives??'—'}</b> colmenas</span></div><small>Registró: ${h(q.created_by_name||'—')}</small></div><div class="queen-rearing-actions"><button class="btn btn-small btn-secondary" data-command="queen-rearing-edit" data-id="${q.id}">Abrir</button><button class="icon-button danger" data-command="queen-rearing-delete" data-id="${q.id}">×</button></div></article>`).join('')}</section>`:empty('♛','Sin crianzas registradas','Inicie un lote para calcular el nacimiento y verlo en el calendario.')}`})}
function calendarModal(data={}){modal(data.id?'Editar evento':'Nuevo evento',`<form data-form="calendar-save"><input type="hidden" name="id" value="${data.id||''}"><input type="hidden" name="app_code" value="comunidad"><label class="field"><span>Título</span><input name="title" required value="${h(data.title||'')}"></label><label class="field"><span>Tipo</span><select name="event_type">${[['general','General'],['zanganos','Arranque de zánganos'],['mielada','Mielada'],['senasa','Calendario SENASA'],['floracion','Floración'],['reunion','Reunión']].map(([v,l])=>`<option value="${v}" ${data.type===v?'selected':''}>${l}</option>`).join('')}</select></label><div class="form-grid two-columns"><label class="field"><span>Desde</span><input type="date" name="start_date" required value="${data.start||today()}"></label><label class="field"><span>Hasta</span><input type="date" name="end_date" value="${data.end||''}"></label></div><label class="field"><span>Notas</span><textarea name="notes">${h(data.notes||'')}</textarea></label><input type="hidden" name="color" value="#6f5bb7"><div class="form-actions"><button class="btn btn-primary">Guardar</button>${data.id?`<button type="button" class="btn btn-danger" data-command="calendar-delete" data-id="${data.id}">Eliminar</button>`:''}</div></form>`,false)}
function monthBounds(offset=0){const d=new Date();d.setDate(1);d.setMonth(d.getMonth()+Number(offset||0));const y=d.getFullYear(),m=d.getMonth(),last=new Date(y,m+1,0).getDate();return{from:`${y}-${String(m+1).padStart(2,'0')}-01`,to:`${y}-${String(m+1).padStart(2,'0')}-${String(last).padStart(2,'0')}`,last,offset:Number(offset||0),label:new Intl.DateTimeFormat('es-AR',{month:'long',year:'numeric'}).format(d)}}
async function calendar(params){
    loading();const offset=Number(params.get('offset')||0),b=monthBounds(offset),d=await api('calendar_events',{params:{app_code:'comunidad',from:b.from,to:b.to}}),first=new Date(b.from+'T12:00:00').getDay(),cells=[];
    for(let i=0;i<first;i++)cells.push('<div class="calendar-day outside"></div>');
    for(let day=1;day<=b.last;day++){
        const date=`${b.from.slice(0,8)}${String(day).padStart(2,'0')}`,events=(d.events||[]).filter(e=>e.start_date<=date&&(e.end_date||e.start_date)>=date),acts=(d.activities||[]).filter(a=>a.start_date===date),isToday=date===today();
        cells.push(`<div class="calendar-day ${isToday?'is-today':''}"><button class="calendar-day-hit" type="button" data-command="calendar-new" data-date="${date}" aria-label="Agregar evento el ${date}"></button><div class="calendar-day-number"><span>${day}</span><button type="button" data-command="calendar-new" data-date="${date}">+</button></div><div class="calendar-day-events">${events.map(e=>`<button class="calendar-event manual" style="--event-color:${h(e.color||'#6f5bb7')}" data-command="calendar-event-open" data-id="${e.id}" data-title="${h(e.title)}" data-type="${h(e.event_type)}" data-start="${e.start_date}" data-end="${e.end_date||''}" data-notes="${h(e.notes||'')}"><strong>${h(e.title)}</strong><small>${cap(e.event_type)}</small></button>`).join('')}${acts.map(a=>`<button class="calendar-event activity" data-command="activity-open" data-id="${a.id}"><strong>${h(a.title)}</strong><small>Actividad</small></button>`).join('')}</div></div>`);
    }
    const eventCount=(d.events||[]).length,activityCount=(d.activities||[]).length;
    shell({title:'Calendario',subtitle:'Actividades y fechas apícolas independientes',active:'calendar',actions:'<button class="btn btn-primary" data-command="calendar-new">+ Nuevo evento</button>',content:`<section class="calendar-shell"><section class="calendar-toolbar panel"><a class="calendar-nav" href="#/calendario-comunidad?offset=${offset-1}" aria-label="Mes anterior">←</a><div class="calendar-month-title"><small>${eventCount} eventos · ${activityCount} actividades</small><h2>${cap(b.label)}</h2></div><a class="calendar-today" href="#/calendario-comunidad?offset=0">Hoy</a><a class="calendar-nav" href="#/calendario-comunidad?offset=${offset+1}" aria-label="Mes siguiente">→</a></section><section class="calendar-grid"><div class="calendar-weekday">Dom</div><div class="calendar-weekday">Lun</div><div class="calendar-weekday">Mar</div><div class="calendar-weekday">Mié</div><div class="calendar-weekday">Jue</div><div class="calendar-weekday">Vie</div><div class="calendar-weekday">Sáb</div>${cells.join('')}</section></section>`})}
async function backups(){loading();const d=await api('community_backups');shell({title:'Copias de seguridad',active:'backups',content:`<section class="backup-hero panel"><div class="backup-illustration">⇩</div><div><h2>Copia completa de Comunidad Apícola</h2><p>Incluye SQL, fotos, actividades y comprobantes.</p></div><button class="btn btn-primary" data-command="backup-create">Descargar TODO en ZIP</button></section><section class="panel"><div class="backup-list">${d.backups.map(b=>`<div class="backup-row"><strong>${h(b.filename)}</strong><small>${dt(b.created_at)}</small><button class="btn btn-small btn-secondary" data-command="open-file" data-type="backup" data-id="${b.id}" data-name="${h(b.filename)}">Descargar</button><button class="icon-button danger" data-command="backup-delete" data-id="${b.id}">×</button></div>`).join('')}</div></section>`})}
async function profile(){const d=await api('me');shell({title:'Mi cuenta',content:`<div class="split-layout"><section class="panel"><h2>${h(d.user.display_name)}</h2><p>Usuario: ${h(d.user.username)}</p><p>Aplicaciones: ${d.user.apps.map(h).join(', ')}</p></section><section class="form-card"><h2>Cambiar contraseña</h2><form data-form="password"><input type="password" name="current_password" placeholder="Actual" required><input type="password" name="new_password" placeholder="Nueva" required><input type="password" name="new_password_confirm" placeholder="Repetir" required><button class="btn btn-primary">Guardar</button></form></section></div>`})}
async function route(){const{path,params}=parse();try{await ensureNavigationOrder();if(path==='/comunidad')return dashboard();if(path==='/colmenas-comunidad')return hives(params);if(path.startsWith('/colmena-comunidad-editar'))return hiveEdit(Number(path.split('/')[2]||0));if(path.startsWith('/colmena-comunidad/'))return hive(Number(path.split('/')[2]));if(path==='/actividades-comunidad')return activities(params);if(path==='/materiales-comunidad')return materials(params);if(path==='/compras-comunidad')return purchases();if(path.startsWith('/compra-comunidad'))return purchase(Number(path.split('/')[2]||0));if(path==='/contabilidad-comunidad')return accounting(params);if(path==='/contabilidad-propia')return personalAccounting(params);if(path==='/crianza-reinas-comunidad')return queenRearing(params);if(path==='/documentos-comunidad')return documents(params);if(path==='/calendario-comunidad')return calendar(params);if(path==='/copias-comunidad')return backups();if(path==='/cuenta-comunidad')return profile();go('/comunidad')}catch(e){shell({title:'No se pudo abrir',content:empty('!',e.message,'Revise la conexión.')})}}
document.addEventListener('submit',async e=>{const f=e.target.closest('form[data-form]');if(!f)return;e.preventDefault();try{const t=f.dataset.form,fd=new FormData(f),obj=Object.fromEntries(fd.entries());if(t==='hive-filter')go('/colmenas-comunidad',obj);else if(t==='hive-save'){const r=await api('community_hive_save',{method:'POST',data:obj});toast(r.message);go(`/colmena-comunidad/${r.id}`)}else if(t==='note-save'){await api('community_hive_note_save',{method:'POST',data:obj});toast('Observación agregada');route()}else if(t==='photo-upload'){await api('community_hive_photo_upload',{method:'POST',formData:fd});toast('Archivo agregado');route()}else if(t==='queen-save'){await api('community_queen_save',{method:'POST',data:obj});toast('Reina agregada');route()}else if(t==='activity-filter')go('/actividades-comunidad',obj);else if(t==='activity-save'){await api('community_activity_save',{method:'POST',formData:fd});closeModal();toast('Actividad guardada');route()}else if(t==='activity-attachment'){await api('community_activity_attachment_upload',{method:'POST',formData:fd});toast('Archivo agregado');activityModal(Number(fd.get('activity_id')))}else if(t==='material-save'){await api('community_material_save',{method:'POST',formData:fd});toast('Material guardado');go('/materiales-comunidad')}else if(t==='material-category-save'){await api('community_material_category_save',{method:'POST',data:obj});toast('Categoría guardada');closeModal();go('/materiales-comunidad')}else if(t==='material-filter')go('/materiales-comunidad',obj);else if(t==='purchase-save'){const r=await api('community_purchase_save',{method:'POST',data:obj});toast('Compra guardada');go(`/compra-comunidad/${r.id}`)}else if(t==='purchase-item-save'){await api('community_purchase_item_save',{method:'POST',data:obj});toast('Elemento agregado');route()}else if(t==='purchase-complete'){await api('community_purchase_complete',{method:'POST',data:obj});closeModal();toast('Compra realizada');route()}else if(t==='account-save'){await api('community_accounting_save',{method:'POST',formData:fd});toast('Movimiento guardado');route()}else if(t==='account-filter')go('/contabilidad-comunidad',obj);else if(t==='personal-account-filter')go('/contabilidad-propia',obj);else if(t==='personal-account-save'){await api('community_personal_accounting_save',{method:'POST',formData:fd});toast('Movimiento privado guardado');route()}else if(t==='document-filter')go('/documentos-comunidad',obj);else if(t==='community-document-save'){await api('document_save',{method:'POST',formData:fd});closeModal();toast('Documento guardado');go('/documentos-comunidad')}else if(t==='queen-rearing-filter')go('/crianza-reinas-comunidad',obj);else if(t==='queen-rearing-save'){await api('queen_rearing_save',{method:'POST',data:obj});closeModal();toast('Crianza guardada y calendario actualizado');go('/crianza-reinas-comunidad')}else if(t==='calendar-save'){await api('calendar_save',{method:'POST',data:obj});closeModal();toast('Evento guardado');route()}else if(t==='password'){await api('change_password',{method:'POST',data:obj});toast('Contraseña actualizada');f.reset()}}catch(err){toast(err.message,'error')}})
document.addEventListener('click',async e=>{const x=e.target.closest('[data-command]');if(!x)return;try{const c=x.dataset.command;if(c==='sidebar')document.getElementById('sidebar')?.classList.toggle('open');else if(c==='switch-toggle'){const m=x.closest('.app-switcher').querySelector('.app-switch-menu');m.hidden=!m.hidden}else if(c==='switch-app'){if(x.dataset.app==='apicultura')location.href='index.html#/dashboard';if(x.dataset.app==='ganaderia')location.href='ganaderia.html#/ganaderia'}else if(c==='logout'){try{await api('logout',{method:'POST',data:{}})}catch(_){}clear();location.href='index.html'}else if(c==='modal-close')closeModal();else if(c==='nav-order-open')openNavigationOrderEditor();else if(c==='nav-order-move'){const row=x.closest('[data-nav-key]'),sib=x.dataset.direction==='up'?row?.previousElementSibling:row?.nextElementSibling;if(row&&sib){if(x.dataset.direction==='up')row.parentElement.insertBefore(row,sib);else row.parentElement.insertBefore(sib,row)}}else if(c==='nav-order-reset'){const box=document.createElement('div');box.innerHTML=navigationOrderRows(nav);document.querySelector('[data-navigation-order-list]').innerHTML=box.querySelector('[data-navigation-order-list]').innerHTML;initNavigationOrderEditor()}else if(c==='nav-order-save'){const order=[...document.querySelectorAll('[data-navigation-order-list] [data-nav-key]')].map(r=>r.dataset.navKey),z=await api('navigation_save',{method:'POST',data:{app_code:'comunidad',order}});state.navigationOrder=z.order;closeModal();toast('Orden personal guardado');await route()}else if(c==='activity-archive-open')openArchivedActivities();else if(c==='activity-open')activityModal(Number(x.dataset.id||0),{hiveId:x.dataset.hiveId});else if(c==='open-file')openFile(x.dataset.type,x.dataset.id,x.dataset.name);else if(c==='hive-delete'){if(confirm('¿Eliminar colmena?')){await api('community_hive_delete',{method:'POST',data:{id:x.dataset.id}});go('/colmenas-comunidad')}}else if(c==='note-delete'){await api('community_hive_note_delete',{method:'POST',data:{id:x.dataset.id}});route()}else if(c==='photo-cover'){await api('community_hive_photo_cover',{method:'POST',data:{id:x.dataset.id,hive_id:x.dataset.hiveId}});route()}else if(c==='photo-delete'){if(confirm('¿Eliminar archivo?')){await api('community_hive_photo_delete',{method:'POST',data:{id:x.dataset.id,hive_id:x.dataset.hiveId}});route()}}else if(c==='queen-toggle'){const p=document.querySelector('[data-queen]');p.hidden=!p.hidden}else if(c==='queen-delete'){await api('community_queen_delete',{method:'POST',data:{id:x.dataset.id,hive_id:x.dataset.hiveId}});route()}else if(c==='activity-delete'){if(confirm('¿Eliminar actividad?')){await api('community_activity_delete',{method:'POST',data:{id:x.dataset.id}});closeModal();route()}}else if(c==='activity-attachment-delete'){await api('community_activity_attachment_delete',{method:'POST',data:{id:x.dataset.id}});activityModal(Number(document.querySelector('[name="activity_id"]')?.value||0))}else if(c==='material-categories-open')openCommunityMaterialCategories();else if(c==='material-category-delete'){if(confirm('¿Eliminar esta categoría vacía?')){await api('community_material_category_delete',{method:'POST',data:{id:x.dataset.id}});closeModal();go('/materiales-comunidad')}}else if(c==='material-delete'){if(confirm('¿Eliminar este material?')){await api('community_material_delete',{method:'POST',data:{id:x.dataset.id}});route()}}else if(c==='purchase-item-delete'){await api('community_purchase_item_delete',{method:'POST',data:{id:x.dataset.id}});route()}else if(c==='purchase-complete')completePurchase(Number(x.dataset.id));else if(c==='account-delete'){await api('community_accounting_delete',{method:'POST',data:{id:x.dataset.id}});route()}else if(c==='personal-account-delete'){if(confirm('¿Eliminar este movimiento privado?')){await api('community_personal_accounting_delete',{method:'POST',data:{id:x.dataset.id}});route()}}else if(c==='document-new')communityDocumentModal();else if(c==='document-edit')communityDocumentModal((state.documents||[]).find(d=>String(d.id)===String(x.dataset.id))||{});else if(c==='document-open')openGenericDocument(x.dataset.id,x.dataset.name);else if(c==='document-delete'){if(confirm('¿Eliminar este documento?')){await api('document_delete',{method:'POST',data:{app_code:'comunidad',id:x.dataset.id}});route()}}else if(c==='queen-rearing-new')queenModal();else if(c==='queen-rearing-edit')queenModal((state.queenBatches||[]).find(q=>String(q.id)===String(x.dataset.id))||{});else if(c==='queen-rearing-delete'){if(confirm('¿Eliminar esta crianza y su evento del calendario?')){await api('queen_rearing_delete',{method:'POST',data:{app_code:'comunidad',id:x.dataset.id}});route()}}else if(c==='calendar-new')calendarModal({start:x.dataset.date||today()});else if(c==='calendar-event-open')calendarModal({id:x.dataset.id,title:x.dataset.title,type:x.dataset.type,start:x.dataset.start,end:x.dataset.end,notes:x.dataset.notes});else if(c==='calendar-delete'){await api('calendar_delete',{method:'POST',data:{id:x.dataset.id,app_code:'comunidad'}});closeModal();route()}else if(c==='backup-create'){const b=await api('community_backup_create',{method:'POST',formData:new FormData(),blob:true}),u=URL.createObjectURL(b),a=document.createElement('a');a.href=u;a.download=`comunidad_${today()}.zip`;a.click();route()}else if(c==='backup-delete'){await api('community_backup_delete',{method:'POST',data:{id:x.dataset.id}});route()}}catch(err){toast(err.message,'error')}})
